CREATE SCHEMA IF NOT EXISTS announcements;

CREATE TABLE IF NOT EXISTS announcements.announcements (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    audience_type announcement_audience_type NOT NULL,
    audience_unit_id UUID NOT NULL,
    publish_from TIMESTAMPTZ NOT NULL,
    publish_until TIMESTAMPTZ,
    status announcement_status NOT NULL DEFAULT 'draft',
    pinned BOOLEAN NOT NULL DEFAULT FALSE,
    targeted_count INTEGER NOT NULL DEFAULT 0,
    created_by UUID,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

